CREATE TYPE invoice_status AS ENUM ('PENDING', 'PAID');
CREATE SEQUENCE invoice_invoice_number_seq INCREMENT BY 1 MINVALUE 1 START 1;
CREATE TABLE customer (id SERIAL NOT NULL, name VARCHAR(255) NOT NULL, street_name VARCHAR(255) NOT NULL, post_code VARCHAR(10) NOT NULL, city VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, PRIMARY KEY(id));
CREATE TABLE invoice (invoice_number INT NOT NULL, customer INT NOT NULL, reference_number INT DEFAULT NULL, created DATE NOT NULL, due DATE NOT NULL, status invoice_status NOT NULL, PRIMARY KEY(invoice_number));
CREATE INDEX IDX_9065174481398E09 ON invoice (customer);
COMMENT ON COLUMN invoice.status IS '(DC2Type:invoice_status)';
CREATE TABLE invoice_item (id SERIAL NOT NULL, invoice INT NOT NULL, description VARCHAR(255) NOT NULL, amount INT NOT NULL, tax INT NOT NULL, price INT NOT NULL, PRIMARY KEY(id));
CREATE INDEX IDX_1DDE477B90651744 ON invoice_item (invoice);
ALTER TABLE invoice ADD CONSTRAINT FK_9065174481398E09 FOREIGN KEY (customer) REFERENCES customer (id) NOT DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE invoice_item ADD CONSTRAINT FK_1DDE477B90651744 FOREIGN KEY (invoice) REFERENCES invoice (invoice_number) NOT DEFERRABLE INITIALLY IMMEDIATE;
